#include "Clock.h"

Clock::Clock(int hours, int minutes) : m_hours{ hours }, m_minutes{ minutes }
{
}

void Clock::tick()
{
    ++m_minutes;
    if (m_minutes == 60)
    {
        m_minutes = 0;
        m_hours = (m_hours + 1) % 24;
    }
}

int Clock::hours() const { return m_hours; }
int Clock::minutes() const { return m_minutes; }
